{"implementation":{"code":"import re

# Parsing the seat request to extract row and seat information

def select_seat(self, user_input: str) -> SeatPreference:
    # Regex to match common seat preferences
    window_seat_pattern = r'(window|aisle|middle|legroom|extra legroom)'
    row_seat_pattern = r'(?P<row>\d+)(?P<seat>[A-F])'

    # Search for window or aisle preferences
    if re.search(window_seat_pattern, user_input, re.IGNORECASE):
        # Check for extra legroom keywords
        extra_legroom = 'extra legroom' in user_input.lower()
        # Match the seat and row
        match = re.search(row_seat_pattern, user_input)
        if match:
            row = int(match.group('row'))
            seat = match.group('seat')
            return SeatPreference(row=row, seat=seat)
        else:
            # Fallback if we find keywords but not a specific row/seat
            return SeatPreference(row=1, seat='A')  # Default to row 1, seat A
    else:
        raise ValueError("Input does not contain a valid seat preference")
